declare n bigint := (select count(*) from public.listing_pin_district where run_id = 'apple-ring-2026-10-25');
begin
  if n = 0 then raise exception 'PROOF: batch 2 loaded no rows'; end if;
  if exists (select 1 from public.listing_pin_district where run_id = 'apple-ring-2026-10-25' and applied) then
    raise exception 'PROOF: a batch 2 row is switched on';
  end if;
  raise notice 'PROOF OK: % batch 2 rows loaded, all switched off', n;
end $proof$;
